import math


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.previous_day_complete = False

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.pending_orders = {}

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        bars = {}

        for symbol in [self.spy, self.aapl, self.ibm, self.bac, self.aig]:
            if not data.ContainsKey(symbol):
                self.previous_day_complete = False
                return
            bar = data[symbol]
            if bar is None:
                self.previous_day_complete = False
                return
            bars[symbol] = bar

        spy_bar = bars[self.spy]
        aapl_bar = bars[self.aapl]

        old_spy_close = self.spy_previous_close
        old_spy_sma = self.spy_previous_sma

        old_aapl_close = self.aapl_previous_close

        self.spy_sma.Update(IndicatorDataPoint(spy_bar.EndTime, spy_bar.Close))
        self.aapl_rsi.Update(IndicatorDataPoint(aapl_bar.EndTime, aapl_bar.Close))

        if old_aapl_close is not None:
            if aapl_bar.Close < old_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        current_spy_sma = (
            self.spy_sma.Current.Value if self.spy_sma.IsReady else None
        )
        current_aapl_rsi = (
            self.aapl_rsi.Current.Value if self.aapl_rsi.IsReady else None
        )

        if (
            not self.IsWarmingUp
            and self.previous_day_complete
            and old_spy_close is not None
            and old_spy_sma is not None
            and current_spy_sma is not None
            and current_aapl_rsi is not None
        ):
            spy_crossed_above = (
                old_spy_close <= old_spy_sma
                and spy_bar.Close > current_spy_sma
            )

            spy_crossed_below = (
                old_spy_close >= old_spy_sma
                and spy_bar.Close < current_spy_sma
            )

            if self.strategy_a_lot == 0 and self.spy_order_pending() is False:
                if spy_crossed_above:
                    quantity = int(
                        math.floor(
                            0.40 * self.Portfolio.TotalPortfolioValue
                            / spy_bar.Close
                        )
                    )
                    if quantity > 0:
                        self.submit_order("A", "buy", quantity)

            elif self.strategy_a_lot > 0 and self.spy_order_pending() is False:
                if spy_crossed_below:
                    self.submit_order("A", "sell", self.strategy_a_lot)

            if self.strategy_b_lot == 0 and self.aapl_order_pending() is False:
                if (
                    self.aapl_red_streak >= 3
                    and self.Portfolio.Cash >= 20000
                ):
                    quantity = int(math.floor(20000 / aapl_bar.Close))
                    if quantity > 0:
                        self.submit_order("B", "buy", quantity)

            elif self.strategy_b_lot > 0 and self.aapl_order_pending() is False:
                if current_aapl_rsi > 60:
                    self.submit_order("B", "sell", self.strategy_b_lot)

        self.spy_previous_close = spy_bar.Close
        self.spy_previous_sma = current_spy_sma
        self.aapl_previous_close = aapl_bar.Close
        self.previous_day_complete = True

    def submit_order(self, strategy, side, quantity):
        symbol = self.spy if strategy == "A" else self.aapl
        signed_quantity = quantity if side == "buy" else -quantity

        ticket = self.MarketOrder(symbol, signed_quantity)

        if ticket is not None:
            self.pending_orders[ticket.OrderId] = (strategy, side)

    def OnOrderEvent(self, order_event):
